#include "unity.h"
#include "xy_apds9960.h"
#include <string.h>
static xy_error_t er;static uint8_t rgb[8]={0x78,0x56,0x34,0x12,0xcd,0xab,0xef,0xbe};
xy_error_t xy_i2c_device_init(xy_i2c_device_t*d,void*h,uint16_t a,uint32_t t){memset(d,0,sizeof(*d));d->base.initialized=1;d->i2c_handle=h;d->dev_addr=a;d->timeout=t;return 0;}xy_error_t xy_i2c_device_read_reg(xy_i2c_device_t*d,uint8_t r,uint8_t*b,size_t n){TEST_ASSERT_TRUE(d->base.initialized);if(er)return er;if(r==XY_APDS9960_REG_ID)*b=0xab;else if(r==XY_APDS9960_REG_CDATAL)memcpy(b,rgb,n);else if(r==XY_APDS9960_REG_PDATA)*b=42;else if(r==XY_APDS9960_REG_GSTATUS)*b=0;return 0;}xy_error_t xy_i2c_device_write_reg(xy_i2c_device_t*d,uint8_t r,const uint8_t*b,size_t n){(void)r;(void)b;(void)n;TEST_ASSERT_TRUE(d->base.initialized);return er;}uint32_t xy_hal_sys_get_tick_count(void){return 77;}void setUp(void){er=0;}void tearDown(void){}
static void ok(void){xy_apds9960_t d;xy_apds9960_rgb_t r;xy_apds9960_proximity_t p;xy_apds9960_gesture_fifo_t g;int bus;TEST_ASSERT_EQUAL_INT(0,xy_apds9960_init(&d,&bus));TEST_ASSERT_EQUAL_INT(0,xy_apds9960_read_rgb(&d,&r));TEST_ASSERT_EQUAL_UINT16(0x5678,r.clear);TEST_ASSERT_EQUAL_UINT16(0x1234,r.red);TEST_ASSERT_EQUAL_INT(0,xy_apds9960_read_proximity(&d,&p));TEST_ASSERT_EQUAL_UINT8(42,p.proximity);TEST_ASSERT_EQUAL_INT(0,xy_apds9960_read_gesture_fifo(&d,&g));TEST_ASSERT_EQUAL_UINT32(77,g.timestamp);TEST_ASSERT_EQUAL_INT(0,xy_apds9960_deinit(&d));}static void fail(void){xy_apds9960_t d;xy_apds9960_rgb_t r={1,2,3,4,5};int bus;TEST_ASSERT_EQUAL_INT(0,xy_apds9960_init(&d,&bus));d.rgb=r;er=XY_DEVICE_TIMEOUT;TEST_ASSERT_EQUAL_INT(XY_DEVICE_TIMEOUT,xy_apds9960_read_rgb(&d,&r));TEST_ASSERT_EQUAL_UINT16(1,r.clear);d.i2c_dev.base.initialized=0;TEST_ASSERT_EQUAL_INT(XY_DEVICE_INVALID_PARAM,xy_apds9960_read_rgb(&d,&r));}int main(void){UNITY_BEGIN();RUN_TEST(ok);RUN_TEST(fail);return UNITY_END();}
